25	pub fn init(app_state: Arc<AppState>, cx: &mut App) {
26	    workspace::register_serializable_item::<ComponentPreview>(cx);
27	
28	    cx.observe_new(move |workspace: &mut Workspace, _window, cx| {
29	        let app_state = app_state.clone();
30	        let project = workspace.project().clone();
31	        let weak_workspace = cx.entity().downgrade();
32	
33	        workspace.register_action(
34	            move |workspace, _: &workspace::OpenComponentPreview, window, cx| {
35	                let app_state = app_state.clone();
36	
37	                let language_registry = app_state.languages.clone();
38	                let user_store = app_state.user_store.clone();
39	
40	                let component_preview = cx.new(|cx| {
41	                    ComponentPreview::new(
42	                        weak_workspace.clone(),
43	                        project.clone(),
44	                        language_registry,
45	                        user_store,
46	                        None,
47	                        None,
48	                        window,
49	                        cx,
50	                    )
51	                    .expect("Failed to create component preview")
52	                });
53	
54	                workspace.add_item_to_active_pane(
55	                    Box::new(component_preview),
56	                    None,
57	                    true,
58	                    window,
59	                    cx,
60	                )
61	            },
62	        );
63	    })
64	    .detach();
65	}
66	
67	enum PreviewEntry {
68	    AllComponents,
69	    Separator,
70	    Component(ComponentMetadata, Option<Vec<usize>>),
71	    SectionHeader(SharedString),
72	}
73	
74	impl From<ComponentMetadata> for PreviewEntry {
75	    fn from(component: ComponentMetadata) -> Self {
76	        PreviewEntry::Component(component, None)
77	    }
78	}
79	
80	impl From<SharedString> for PreviewEntry {
81	    fn from(section_header: SharedString) -> Self {
82	        PreviewEntry::SectionHeader(section_header)
83	    }
84	}
