786	    fn deserialize(
787	        project: Entity<Project>,
788	        workspace: WeakEntity<Workspace>,
789	        workspace_id: WorkspaceId,
790	        item_id: ItemId,
791	        window: &mut Window,
792	        cx: &mut App,
793	    ) -> Task<anyhow::Result<Entity<Self>>> {
794	        let deserialized_active_page =
795	            match ComponentPreviewDb::global(cx).get_active_page(item_id, workspace_id) {
796	                Ok(page) => {
797	                    if let Some(page) = page {
798	                        ActivePageId(page)
799	                    } else {
800	                        ActivePageId::default()
801	                    }
802	                }
803	                Err(_) => ActivePageId::default(),
804	            };
805	
806	        let user_store = project.read(cx).user_store();
807	        let language_registry = project.read(cx).languages().clone();
808	        let preview_page = if deserialized_active_page.0 == ActivePageId::default().0 {
809	            Some(PreviewPage::default())
810	        } else {
811	            let component_str = deserialized_active_page.0;
812	            let component_registry = components();
813	            let all_components = component_registry.components();
814	            let found_component = all_components.iter().find(|c| c.id().0 == component_str);
815	
816	            if let Some(component) = found_component {
817	                Some(PreviewPage::Component(component.id()))
818	            } else {
819	                Some(PreviewPage::default())
820	            }
821	        };
822	
823	        window.spawn(cx, async move |cx| {
824	            let user_store = user_store.clone();
